export const GOGETA_BLUE_SKILLS={meteorassault:{cooldown:8,duration:1},stardustbreaker:{cooldown:10,cast:.45,duration:.85},godpunisher:{cooldown:11,cast:.3,duration:1},bluecombo:{duration:.62}};
export const gogeta_blue={name:'Gogeta Blue',assets:['gogeta_blue','gogeta_blue_cast','gogeta_blue_intro','gogeta_blue_vfx','gogeta_blue_intro_vfx','gogeta_blue_ultimate_actor','gogeta_blue_ultimate_vfx','gogeta_blue_dialogue'],stats:{hp:1200,speed:235,melee:84,skillPower:100,cooldown:100,aggression:80,preferredRange:100,blockChance:15,blinkChance:0},rangedBasic:true,
 init(f){Object.assign(f,{rage:0,rageLockUntil:0,rageReadyTick:null,personalUses:0,blueHits:0,blueVolley:0});for(const [k,delay] of Object.entries({meteorassault:1,stardustbreaker:3,godpunisher:5})){f[k+'Cd']=delay*f.cooldownFactor;f.skillUses[k]=0;}f.skillUses.bluecombo=0;},
 tick(f,dt){for(const k of ['meteorassault','stardustbreaker','godpunisher'])f[k+'Cd']=Math.max(0,f[k+'Cd']-dt);},
 onAct(f,state,d){const spec=GOGETA_BLUE_SKILLS[state];if(!spec)return;f.skillUses[state]++;f.blueHits=0;f.blueVolley=0;f.blueTarget=d.pickTarget(f)?.uid;if(spec.cooldown)f[state+'Cd']=spec.cooldown*f.cooldownFactor;else f.cd=.9*f.cooldownFactor;},
 updateAction(d,f,o,hits,dx,dy,distance,dt){const spec=GOGETA_BLUE_SKILLS[f.state];if(!spec)return false;const target=d.fighters.find(t=>t.uid===f.blueTarget&&t.hp>0&&d.isEnemy(f,t))||o;
  if(f.state==='meteorassault'){
   const x=target.x-f.x,y=target.y-f.y,n=Math.hypot(x,y)||1;
   if(f.age>=.12&&f.age<.48&&d.tick>=(f.rootUntil||0)){const travel=Math.min(Math.max(0,n-65),900*dt);f.x+=x/n*travel;f.y+=y/n*travel;f.actionX=x/n;f.actionY=y/n;f.face=Math.sign(x)||f.face;d.clampPosition(f);}
   while(f.blueHits<3&&f.age>=[.38,.55,.74][f.blueHits]){const index=f.blueHits++;if(Math.hypot(target.x-f.x,target.y-f.y)<115){hits.push({source:f,target,value:[50,55,95][index],kind:'skill',knockback:index===2?38:0});d.event('gogetaBlueImpact',f,{x:target.x,y:target.y,skill:'meteorassault'});}else d.event('miss',f);}
  }else if(f.state==='bluecombo'){
   while(f.blueHits<3&&f.age>=[.16,.31,.48][f.blueHits]){const index=f.blueHits++,x=target.x-f.x,y=target.y-f.y,n=Math.hypot(x,y)||1;if(n<103&&(x*f.actionX+y*f.actionY)/n>.2){hits.push({source:f,target,value:f.melee*[.28,.30,.42][index],kind:'melee',knockback:index===2?16:0});d.event('gogetaBlueImpact',f,{x:target.x,y:target.y,skill:'bluecombo'});}else d.event('miss',f);}
  }else if(f.state==='godpunisher'){
   while(f.blueVolley<5&&f.age>=.3+f.blueVolley*.11){const index=f.blueVolley++,angle=Math.atan2(target.y-f.y,target.x-f.x)+(index-2)*.045;d.shots.push({id:f.id,ownerUid:f.uid,kind:'godpunisher',skill:'godpunisher',damage:48,radius:23,x:f.x+Math.cos(angle)*42,y:f.y+Math.sin(angle)*42,vx:Math.cos(angle)*650,vy:Math.sin(angle)*650,life:1.3,impactEvent:'gogetaBlueImpact',requiresOwnerAlive:true});d.event('fire',f,{skill:f.state});}
  }else if(f.age>=spec.cast&&!f.hit){f.hit=true;const angle=Math.atan2(target.y-f.y,target.x-f.x);d.shots.push({id:f.id,ownerUid:f.uid,kind:'stardustbreaker',skill:'stardustbreaker',damage:230,radius:27,splash:115,splashDamage:75,x:f.x+Math.cos(angle)*45,y:f.y+Math.sin(angle)*45,vx:Math.cos(angle)*540,vy:Math.sin(angle)*540,life:1.5,impactEvent:'gogetaBlueImpact',requiresOwnerAlive:true});d.event('fire',f,{skill:f.state});}
  if(f.age>=spec.duration){f.state='idle';f.age=0;}return true;
 },
 chooseSkill(d,f,o,dx,dy,distance){if(f.meteorassaultCd===0&&distance>110&&distance<420){d.act(f,'meteorassault',dx,dy);return true;}if(distance>140&&distance<650){for(const k of ['stardustbreaker','godpunisher'])if(f[k+'Cd']===0){d.act(f,k,dx,dy);return true;}}return false;},
 chooseBasic(d,f,o,dx,dy,distance){if(f.cd===0&&distance<100){d.act(f,'bluecombo',dx,dy);return true;}const n=distance||1;if(distance<125&&f.cd>0){f.moveX=-dx/n*.8-dy/n*.4;f.moveY=-dy/n*.8+dx/n*.4;}else{f.moveX=dx/n;f.moveY=dy/n;}f.state='run';return true;},
 ultimateCinematic(d,f,c){if(c.elapsed>18||d.tick<(f.rootUntil||0))return;const beforeX=f.x,beforeY=f.y;f.x-=c.dx*10;f.y-=c.dy*10;d.clampPosition(f);c.x=f.x;c.y=f.y;if(c.elapsed===1)d.event('gogetaBlueRetreat',f,{x:beforeX,y:beforeY});}
};
export function gogetaBluePose(f,hurt=false){const state=hurt?'hurt':f.state;if(['meteorassault','stardustbreaker','godpunisher'].includes(state))return {key:'gogeta_blue_cast',row:['meteorassault','stardustbreaker','godpunisher'].indexOf(state),frame:Math.min(3,Math.floor(f.age/GOGETA_BLUE_SKILLS[state].duration*4))};if(state==='bluecombo')return {key:'gogeta_blue',row:f.age<.4?2:3,frame:Math.min(3,Math.floor(f.age/.62*4))};return {key:'gogeta_blue',row:({idle:0,run:1,melee:2,dash:4,guard:5,hurt:6,defeat:7})[state]??0,frame:['dash','hurt','defeat'].includes(state)?Math.min(3,Math.floor(f.age*10)):Math.floor(f.age*10)%4};}
